INSERT INTO _Locale ("LocaId","LocaText") VALUES ('infoid_arm_rezept_d_pauldrons','Smithing 11. Makes Pauldrons of the Hearthguard.\nChest 2, Back 2, Arms 3; metal, encumbrance 0.5\nLE +10\nConsumes: 1 Dwarven Shoulder Plates, 1 Dwarven steel, 3 Leather strips.\nThe source item can be bought again.');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('lookat_arm_d_helm','Helm of the Deep Watch');
