INSERT INTO _Locale ("LocaId","LocaText") VALUES ('lookat_arm_w_scale_cuirass','Wyrmscale Cuirass');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('infoid_arm_w_scale_cuirass','Purplewyrm scales riveted over plate. Heavy, hot and nearly impenetrable.\n\nLE +10\nImmune to burning');
