INSERT INTO _Locale ("LocaId","LocaText") VALUES ('infoid_arm_rezept_w_scale_cuirass','Smithing 13. Makes Wyrmscale Cuirass.\nChest 6, Belly 7, Back 7, Arms 3, Legs 2; metal, encumbrance 4.8\nLE +10; Immune to burning\nConsumes: 1 Light Plate Armor, 3 Heavy Wyrm Scale, 1 Dwarven steel.\nThe source item can be bought again.');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('lookat_arm_w_hide_jerkin','Wyrmhide Jerkin');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('infoid_arm_w_hide_jerkin','Flexible scales on dragon-blooded leather. No metal: fighters and casters alike.\n\nImmune to burning\nImmune to knockdown');
