INSERT INTO _Locale ("LocaId","LocaText") VALUES ('infoid_arm_rezept_w_hide_jerkin','Smithing 12. Makes Wyrmhide Jerkin.\nChest 5, Belly 5, Back 5, Arms 1; leather, encumbrance 1.7\nImmune to burning; Immune to knockdown\nConsumes: 1 Leather Doublet., 2 Heavy Wyrm Scale, 2 Dragon blood, 4 Leather strips.\nThe source item can be bought again.');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('lookat_arm_w_blood_robe','Dragonblood Robe');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('infoid_arm_w_blood_robe','A robe soaked in Purplewyrm blood and lined with one scale over the heart.\n\nAE +10, Magic resistance +2\nImmune to burning');
