INSERT INTO _Locale ("LocaId","LocaText") VALUES ('infoid_arm_rezept_w_blood_robe','Alchemy 12. Makes Dragonblood Robe.\nChest 4, Belly 4, Back 4, Arms 1; cloth, encumbrance 1.0\nAE +10, Magic resistance +2; Immune to burning\nConsumes: 1 Robe of the City of Ferdok, 1 Heavy Wyrm Scale, 3 Dragon blood, 2 Gold leaf.\nThe source item can be bought again.');
