INSERT INTO _Locale ("LocaId","LocaText") VALUES ('infoid_arm_rezept_w_scale_shield','Smithing 11. Makes Wyrmscale Shield.\nAT -1, PA +3\nConstitution +1; Immune to burning\nConsumes: 1 Iron Shield, 2 Heavy Wyrm Scale.\nThe source item can be bought again.');
