INSERT INTO _Locale ("LocaId","LocaText") VALUES ('infoid_arm_l_phex_laugh','A dragon-tooth dagger stolen from Japhgur himself. Twice.\n\nPick Pocket +2, Agility +1, Dexterity +1\n20% on hit: Dazed\n15% on hit: Wyrm Venom\nAgainst dazed foes: +1d6 damage\n10% on hit: wielder gains Quickstep');
