INSERT INTO _Locale ("LocaId","LocaText") VALUES ('infoid_arm_w_moonshadow','A saber that seems to slip sideways out of every parry.\n\n12% on hit: wielder gains Shadowstep');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('lookat_arm_w_whisperwind','Whisperwind');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('infoid_arm_w_whisperwind','A quick short bow; its arrows arrive before their sound.\n\nOn hit: +1 damage\n12% on hit: Dazed');
