INSERT INTO _Locale ("LocaId","LocaText") VALUES ('infoid_arm_rezept_mh_grips','Bowcraft 9. Makes Moonhowl Grips.\nArms 2; leather, encumbrance 0.2\nBow +2, Brawling +1, Dexterity +1\nConsumes: 1 Darkwolf Grips, 1 Moon-mad Pelt, 2 Moon-mad Sinew.\nThe source item can be bought again.');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('lookat_arm_mh_bow','Moonhowl Longbow');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('infoid_arm_mh_bow','A longbow strung with moon-mad sinew. When it looses, the string howls, and sometimes lightning answers.\n\nOn hit: +1 damage\n20% on hit: +1d6 magic damage');
