INSERT INTO _Locale ("LocaId","LocaText") VALUES ('infoid_arm_rezept_mh_bow','Bowcraft 10. Makes Moonhowl Longbow.\n3D6+2 HP, AT +1, reload 2 CR\nOn hit: +1 damage; 20% on hit: +1d6 magic damage\nConsumes: 1 Longbow, 3 Moon-mad Sinew, 1 Elf wood.\nThe source item can be bought again.');
