INSERT INTO _Locale ("LocaId","LocaText") VALUES ('infoid_arm_mh_iryan_shoulders','Iryan leather shoulder guards with Stormhowl''s heartstone sewn under the left plate. Lightning-quick, and spells slide off them.\n\nMagic resistance +2, Dodge +1, Perception +2');
