INSERT INTO _Locale ("LocaId","LocaText") VALUES ('infoid_arm_tc_cuirass','A leather cuirass plated with split boar tusk. Ugly, heavy-shouldered and very hard to cut.\n\nLE +5, Willpower +1\nSet (Tuskhide): LE +2 for each piece you own; all four: Willpower +2, AU +5 (re-equip after finding a piece)');
