INSERT INTO _Locale ("LocaId","LocaText") VALUES ('infoid_arm_rezept_tc_cuirass','Smithing 5. Makes Tuskhide Cuirass.\nChest 4, Belly 4, Back 4, Arms 1; leather, encumbrance 2.0\nLE +5, Willpower +1; Set (Tuskhide): LE +2 for each piece you own; all four: Willpower +2, AU +5 (re-equip after finding a piece)\nConsumes: 1 Leather Cuirass, 4 Boar Tusk, 2 Leather strips.\nThe source item can be bought again.');
