INSERT INTO _Locale ("LocaId","LocaText") VALUES ('infoid_arm_ts_cuirass','The Tuskhide Cuirass, faced with giant-crab shell over the chest. Blades skid off it like oars off a hull.\n\nLE +8, Willpower +2, Magic resistance +1\nSet (Ironshell): LE +3 for each piece you own; all four: Parry +1, Magic resistance +1 (re-equip after finding a piece)');
