INSERT INTO _Locale ("LocaId","LocaText") VALUES ('infoid_arm_tw_cuirass','Ironshell reinforced with Kosh steel, crypt-louse chitin and a tatzelwurm fang over the heart. You do not fall down any more.\n\nLE +12, Courage +1, Strength +1\nImmune to knockdown\nSet (The Warlord): LE +4 for each piece you own; all four: Attack +1, Parry +1 (re-equip after finding a piece)');
