INSERT INTO _Locale ("LocaId","LocaText") VALUES ('infoid_arm_ww_robe','A green robe re-woven with spider silk and dyed in troll-toad sap, the way the forest witches do it.\n\nAE +10, Magic resistance +1, Plant Lore +2\nSet (Witchweave): AE +2 for each piece you own; all four: Magic resistance +1, Intuition +1 (re-equip after finding a piece)');
