INSERT INTO _Locale ("LocaId","LocaText") VALUES ('infoid_arm_we_robe','The Witchweave Robe threaded with glowing firefly silk and a green eye at the collar. Fire will not take it.\n\nAE +15, Magic resistance +2, Plant Lore +2\nImmune to burning\nSet (Emberweave): AE +3 for each piece you own; all four: Magic resistance +2, Cleverness +1 (re-equip after finding a piece)');
