INSERT INTO _Locale ("LocaId","LocaText") VALUES ('lookat_arm_am_barbed_arrow','Barbed Arrows');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('infoid_arm_am_barbed_arrow','Wicked barbs that tear on the way out.\n\n6% on hit: Wound');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('lookat_arm_rezept_am_barbed_arrow','Instructions for Barbed Arrows');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('infoid_arm_rezept_am_barbed_arrow','Bowcraft 4. Makes 20 Barbed Arrows.\n6% on hit: Wound\nNeeds: 1 Elm wood, 1 Wood glue, 2 Arrow heads, 1 Goose feathers.');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('lookat_arm_am_barbed_bolt','Barbed Bolts');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('infoid_arm_am_barbed_bolt','Crossbow bolts with barbed heads.\n\n6% on hit: Wound');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('lookat_arm_rezept_am_barbed_bolt','Instructions for Barbed Bolts');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('infoid_arm_rezept_am_barbed_bolt','Bowcraft 4. Makes 20 Barbed Bolts.\n6% on hit: Wound\nNeeds: 1 Elm wood, 1 Wood glue, 2 Bolt heads, 1 Goose feathers.');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('lookat_arm_am_kosh_arrow','Kosch Hunter''s Arrows');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('infoid_arm_am_kosh_arrow','Kosch hunters grind boar tusk and wolf fang into heads harder than iron and bind them with sinew. They punch through leather and mail.\n\nOn hit: +3 damage');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('lookat_arm_rezept_am_kosh_arrow','Instructions for Kosch Hunter''s Arrows');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('infoid_arm_rezept_am_kosh_arrow','Bowcraft 9. Makes 20 Kosch Hunter''s Arrows.\nOn hit: +3 damage\nNeeds: 1 Yew wood, 1 Wood glue, 1 Boar Tusk, 1 Wolf Fang, 1 Sinews, 1 Goose feathers.');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('lookat_arm_am_thunder_arrow','Thunderhead Arrows');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('infoid_arm_am_thunder_arrow','A chip of gemstone in each head stores a spark.\n\nOn hit: +1d6 magic damage');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('lookat_arm_rezept_am_thunder_arrow','Instructions for Thunderhead Arrows');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('infoid_arm_rezept_am_thunder_arrow','Bowcraft 12. Makes 10 Thunderhead Arrows.\nOn hit: +1d6 magic damage\nNeeds: 1 Yew wood, 1 Wood glue, 1 Arrow heads, 1 Harpy feathers, 1 Gemstones.');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('lookat_arm_am_frost_arrow','Frost-fletched Arrows');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('infoid_arm_am_frost_arrow','Harpy feathers dipped in meltwater from Firun''s glaciers.\n\nOn hit: +1 magic damage\n20% on hit: Cold Shock (Corpofrigo)');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('lookat_arm_rezept_am_frost_arrow','Instructions for Frost-fletched Arrows');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('infoid_arm_rezept_am_frost_arrow','Bowcraft 12. Makes 10 Frost-fletched Arrows.\nOn hit: +1 magic damage; 20% on hit: Cold Shock (Corpofrigo)\nNeeds: 1 Yew wood, 1 Wood glue, 1 Arrow heads, 2 Harpy feathers.');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('lookat_arm_am_dwarf_bolt','Dwarven Steel Bolts');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('infoid_arm_am_dwarf_bolt','Square-headed bolts of Angrosch steel.\n\nOn hit: +4 damage\n10% on hit: Knockdown');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('lookat_arm_rezept_am_dwarf_bolt','Instructions for Dwarven Steel Bolts');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('infoid_arm_rezept_am_dwarf_bolt','Bowcraft 14. Makes 20 Dwarven Steel Bolts.\nOn hit: +4 damage; 10% on hit: Knockdown\nNeeds: 1 Dwarven steel, 2 Bolt heads, 1 Wood glue, 1 Goose feathers.');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('lookat_arm_am_wyrmfang_arrow','Wyrmfang Arrows');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('infoid_arm_am_wyrmfang_arrow','Tipped with splinters of a dragon''s tooth. They burn going in.\n\nOn hit: +8 fire damage\n15% on hit: Burning');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('lookat_arm_rezept_am_wyrmfang_arrow','Instructions for Wyrmfang Arrows');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('infoid_arm_rezept_am_wyrmfang_arrow','Bowcraft 16. Makes 10 Wyrmfang Arrows.\nOn hit: +8 fire damage; 15% on hit: Burning\nNeeds: 1 Dragon tooth, 1 Dragon sinew, 3 Harpy feathers, 3 Wood glue.');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('lookat_arm_am_moonsilver_arrow','Moonsilver Arrows');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('infoid_arm_am_moonsilver_arrow','Silver-tipped: the dead fear them.\n\nAgainst the undead: +1d6+2 magic damage');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('lookat_arm_rezept_am_moonsilver_arrow','Instructions for Moonsilver Arrows');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('infoid_arm_rezept_am_moonsilver_arrow','Bowcraft 8. Makes 20 Moonsilver Arrows.\nAgainst the undead: +1d6+2 magic damage\nNeeds: 1 Elm wood, 1 Wood glue, 2 Arrow heads, 1 Goose feathers, 1 Gemstones.');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('lookat_arm_am_hawk_arrow','Hawk-feather Arrows');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('infoid_arm_am_hawk_arrow','Fletched with hawk feathers: they bite deeper.\n\nOn hit: +1 damage');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('lookat_arm_rezept_am_hawk_arrow','Instructions for Hawk-feather Arrows');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('infoid_arm_rezept_am_hawk_arrow','Bowcraft 8. Makes 20 Hawk-feather Arrows.\nOn hit: +1 damage\nNeeds: 1 Elm wood, 1 Wood glue, 2 Arrow heads, 1 Harpy feathers.');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('lookat_arm_am_sleepthorn_arrow','Sleepthorn Arrows');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('infoid_arm_am_sleepthorn_arrow','Tipped with sleepthorn sap: the target staggers.\n\n15% on hit: Stun');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('lookat_arm_rezept_am_sleepthorn_arrow','Instructions for Sleepthorn Arrows');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('infoid_arm_rezept_am_sleepthorn_arrow','Bowcraft 9. Makes 20 Sleepthorn Arrows.\n15% on hit: Stun\nNeeds: 1 Elm wood, 1 Wood glue, 2 Arrow heads, 1 Goose feathers, 1 Alcohol.');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('lookat_arm_am_moon_arrow','Moon-sinew Arrows');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('infoid_arm_am_moon_arrow','Fletched with a twist of moon-mad sinew. The shaft hums in flight, and sometimes sparks.\n\nOn hit: +1 damage\n15% on hit: +1d6 magic damage');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('lookat_arm_rezept_am_moon_arrow','Instructions for Moon-sinew Arrows');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('infoid_arm_rezept_am_moon_arrow','Bowcraft 9. Makes 10 Moon-sinew Arrows.\nOn hit: +1 damage; 15% on hit: +1d6 magic damage\nNeeds: 1 Yew wood, 1 Wood glue, 1 Arrow heads, 1 Moon-mad Sinew.');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('infoid_weapon_crafted_unique_kurzschwert','An archaic saber, masterfully crafted from one of the Purplewyrm Japhgur''s knife-like teeth.\n\n1D6+10 HP\nImmune to burning\n15% on hit: Burning\nAgainst burning foes: +1d6 fire damage\n8% on hit: Wound');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('infoid_weapon_crafted_unique_wurmspiess','An archaic pole weapon, expertly crafted from one of the Purplewyrm Japhgur''s knife-like teeth.\n\n2D6+8 HP\nImmune to burning\n15% on hit: Knockdown\nAgainst downed foes: +1d6 damage\n10% on hit: Burning');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('infoid_weapon_crafted_unique_bogen','An expertly crafted composite bow of metal, premium wood, and horn from the Purplewyrm Japhgur.\n\nReload time: 1 CR\n\n4D6+5 HP\nImmune to burning\nOn hit: +1d6 fire damage\n10% on hit: Burning');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('infoid_weapon_crafted_unique_armbrust','An expertly crafted crossbow of metal and horn from the Purplewyrm Japhgur.\n\nReload time: 4 CR\n\n3D6+14 HP\nImmune to burning\n20% on hit: Stun\nAgainst stunned foes: +1d6 damage\n10% on hit: Burning');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('infoid_weapon_unique_zyklopen_saebel','A masterfully crafted saber from the embers of the Fire Falls of Algormosh. The weapon lies featherlight in the hand and the slender blade is razor sharp.\n\n1D6+12 HP\nImmune to burning\n15% on hit: Burning\nAgainst burning foes: +1d6 fire damage');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('infoid_weapon_unique_zyklopen_schwert','This Longsword was forged by a master from the embers of the Fire Falls of Algormosh. The glittering metal is almost weightless in the hand and the thin blade is unequalled in its sharpness.\n\n1D6+12 HP\nImmune to burning\n15% on hit: Burning\nAgainst burning foes: +1d6 fire damage');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('infoid_weapon_unique_zyklopen_axt','An axe masterfully crafted from the embers of the Fire Falls of Algormosh. The glittering metal is almost weightless in the hand and the thin blade is unequalled in its sharpness.\n\n1D6+12 HP\nImmune to burning\n15% on hit: Burning\nAgainst burning foes: +1d6 fire damage');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('infoid_weapon_unique_zyklopen_zweihandschwert','Flamestrike'' - is the worthy name of this masterfully crafted two-handed sword from the embers of the Fire Falls of Algormosh. The gleaming metal is wonderfully light and the slender, yet extremely strong, blade is so sharp that it slices through armor as effortlessly as a hot knife through butter.\n\n2D6+10 HP\nImmune to burning\n15% on hit: Burning\n12% on hit: Knockdown');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('infoid_weapon_unique_zyklopen_zweihandaxt','The dual blade of this axe from the embers of the Fire Falls of Algormosh is made of glittering metal. The blades are sharper than any razor and this weapon''s balance is incomparable.\n\n3D6+4 HP\nImmune to burning\n15% on hit: Burning\n12% on hit: Knockdown');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('infoid_weapon_unique_zyklopen_speer','Firespike'' - is the name given to this masterfully crafted spear from the embers of the Fire Falls of Algormosh. This spear is almost weightless and is perfectly balanced. Its point is sharp enough to effortlessly penetrate any material, including the toughest steel.\n\n1D6+13 HP\nImmune to burning\n15% on hit: Burning\n15% on hit: Knockdown');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('infoid_weapon_unique_zyklopen_schwererdolch','This Heavy Dagger was forged by a master in the embers of the Fire Falls of Algormosh. The glittering metal is barely discernable in the hand and the thin blade is so sharp that this dagger should be used only with care.\n\n1D6+10 HP\nImmune to burning\n15% on hit: Burning\n10% on hit: Wound');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('infoid_weapon_unique_zyklopen_rapier','Sparksting'' - is the extremely apt name for this masterfully-crafted rapier. The gleaming metal lies almost weightless in the hand and the slim blade is of an unparalleled sharpness and elegance.\n\n1D6+11 HP\nImmune to burning\n15% on hit: Burning\n12% on hit: Dazed');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('infoid_weapon_unique_zyklopen_stab','This fighting staff was forged from the embers of the Fire Falls of Algormosh. It glitters in the sun and rests perfectly balanced in the hand.\n\n1D6+11 HP\nImmune to burning\n15% on hit: Burning\nOn hit: restores 2 AE to the wielder');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('infoid_weapon_unique_zyklopen_bogen','This Cyclopean Composite Bow was crafted by a master from the finest Aventurian woods and magical titanium. It is very light and flexible. It is also effortlessly drawn, as if by a magic hand.\n\nReload time: 0 CR\n\n2D6+6 HP\nImmune to burning\n15% on hit: Burning\nAgainst burning foes: +1d6 fire damage');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('infoid_weapon_unique_zyklopen_armbrust','Flamesnap'' is the worthy name of this cyclopean crossbow, masterfully crafted from the finest Aventurian woods and gleaming steel from the embers of the Fire Falls of Algormosh. This crossbow lies almost weightless in the hand and can be pulled without expending much energy.\n\nFire rate: 2 CR\n\n2D6+14 HP\nImmune to burning\n15% on hit: Burning\n20% on hit: Stun');
